    await page.route('**/api/**', r => r.request().url().endsWith('/api/health') || r.request().url().endsWith('/api/auth/me') ? r.fallback() : json(r, { detail: 'orchestrator unavailable: OPENAI_API_KEY is not set' }, 503))
