          onChange={(value) => { setLine(value as Line); setFeatureId(''); setIncluded(true) }} />
        <Choice label="Optional feature" value={featureId} items={[...options.map((o) => ({ value: o.citation.id, label: `${o.meta.code ? `${o.meta.code} · ` : ''}${o.text}` })), { value: 'custom', label: 'Custom optional feature' }]}
          onChange={(value) => { setFeatureId(value); setIncluded(true) }} />
      </div>
      {catalog.state === 'loading' && <div className="mt-4 flex items-center gap-3" role="status"><Skeleton className="h-4 w-32" /><span className="text-xs text-muted-foreground">Loading optional equipment...</span></div>}
      {catalog.state === 'error' && <div className="mt-4 flex flex-wrap items-center gap-3"><p role="alert" className="text-sm text-destructive">{catalog.message} You can use a custom feature.</p><Button variant="outline" size="sm" onClick={() => setRetry((n) => n + 1)}>Retry catalog</Button></div>}
      {catalog.state === 'ready' && catalog.data.options.length === 0 && <p className="mt-4 text-sm text-muted-foreground">No optional equipment is loaded for {line}. Choose a custom feature to explore a scenario.</p>}
      {catalog.state === 'ready' && catalog.data.truncated && <p className="mt-4 text-xs text-muted-foreground">Showing the first 200 catalog options. Use a custom feature for other equipment.</p>}
      {featureId === 'custom' && <div className="mt-4 space-y-2"><Label htmlFor="custom-feature">Feature name</Label><Input id="custom-feature" value={custom} maxLength={120} onChange={(e) => setCustom(e.target.value)} placeholder="Name the optional feature" /><p className="text-xs text-muted-foreground">Custom feature, with no catalog evidence attached.</p></div>}
      {option && <p className="mt-4 text-sm text-muted-foreground">Optional on at least one catalog variant. Catalog availability does not establish market impact. <CitationChip n="Catalog" sourceRef={option.citation} /></p>}
    </section>

